(r, big) => {
    const n = big ? 50000 : r.int(1, 7);
    const order = r.shuffle(Array.from({ length: n }, (_, i) => i)); // edges that follow this order never form a loop
    const m = big ? 100000 : r.int(0, 9), rules = [];
    if (big) for (let i = 0; i + 1 < n; i++) rules.push([order[i], order[i + 1]]); // one long chain
    while (n > 1 && rules.length < m) {
      const i = r.int(0, n - 1), j = r.int(0, n - 1);
      if (i !== j) rules.push(i < j ? [order[i], order[j]] : [order[j], order[i]]);
    }
    if (r.bool(0.5)) { // maybe add one rule that points backwards (or a self-rule when j = i)
      const i = r.int(0, n - 1), j = r.int(0, i);
      rules[r.int(0, Math.max(0, rules.length - 1))] = [order[i], order[j]];
    }
    return [n, r.shuffle(rules)];
  }

