function canTakeAll(n: number, rules: number[][]): boolean {
  const after: number[][] = Array.from({ length: n }, () => []);
  for (const [a, b] of rules) after[a].push(b);
  const color = new Array(n).fill(0); // 0 white, 1 grey, 2 black
  for (let s = 0; s < n; s++) {
    if (color[s] !== 0) continue;
    color[s] = 1;
    const stack: number[][] = [[s, 0]]; // [course, index of the next arrow to follow]
    while (stack.length) {
      const top = stack[stack.length - 1], u = top[0];
      if (top[1] < after[u].length) {
        const v = after[u][top[1]++];
        if (color[v] === 1) return false; // back to a course on the current path
        if (color[v] === 0) { color[v] = 1; stack.push([v, 0]); }
      } else {
        color[u] = 2;
        stack.pop();
      }
    }
  }
  return true;
}

