function canTakeAll(n: number, rules: number[][]): boolean {
  const after: number[][] = Array.from({ length: n }, () => []);
  const indeg = new Array(n).fill(0);
  for (const [a, b] of rules) { after[a].push(b); indeg[b]++; }
  const queue: number[] = [];
  for (let c = 0; c < n; c++) if (indeg[c] === 0) queue.push(c);
  for (let head = 0; head < queue.length; head++)
    for (const b of after[queue[head]])
      if (--indeg[b] === 0) queue.push(b);
  return queue.length === n; // every course was taken exactly once
}

